"""Independent Auto Stream V2 control screen. Existing Short Stream UI intact."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(prefix="/engine", tags=["Auto Stream Studio"])

PAGE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Auto Stream</title>\n<style>\n:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#172136;background:#f5f7fb;--line:#e2e7f0;--muted:#64748b;--accent:#4f46e5;--good:#15803d;--warn:#a16207}\n*{box-sizing:border-box}body{margin:0;background:#f5f7fb}main{max-width:1320px;margin:0 auto;padding:24px 20px 40px}h1,h2,h3{margin:0 0 10px}h1{font-size:25px}h2{font-size:18px}h3{font-size:14px}.lede{color:var(--muted);font-size:13px;margin:0 0 18px}.rail{display:flex;gap:6px;overflow-x:auto;border-bottom:1px solid #cfd7e5;margin-bottom:18px}.rail button{border:1px solid #cfd7e5;border-bottom:0;background:#eef1f6;color:#35445f;padding:11px 16px;border-radius:8px 8px 0 0;cursor:pointer;font-weight:750;white-space:nowrap}.rail button[aria-selected=true]{background:#fff;color:var(--accent);border-top:3px solid var(--accent);padding-top:9px}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 4px 18px #1f2a440b;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.stat{border:1px solid var(--line);border-radius:12px;padding:14px}.stat b{display:block;font-size:24px}.stat span,.muted{color:var(--muted);font-size:12px}.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.item{border:1px solid var(--line);border-radius:10px;padding:12px;margin:9px 0}.item strong{display:block}.btn,button{border:1px solid #cbd5e1;background:#fff;color:#172136;padding:9px 12px;border-radius:8px;cursor:pointer;font-weight:700}.btn.primary,button.primary{background:var(--accent);color:#fff;border-color:var(--accent)}.btn.good{background:var(--good);color:#fff;border-color:var(--good)}.btn.warn{background:#fef3c7;color:#854d0e;border-color:#fcd34d}.btn:disabled,button:disabled{opacity:.5;cursor:not-allowed}input,select,textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;font:inherit;background:#fff}label{font-size:12px;font-weight:750;display:block;margin:9px 0 5px}.message{white-space:pre-wrap;background:#eef2ff;border-radius:9px;padding:11px;color:#334155;font-size:13px}.danger{color:#b91c1c}.mono{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.queue-state{font-size:11px;border-radius:999px;padding:5px 8px;background:#eef2f7;color:#475569}.queue-state.live{background:#dcfce7;color:#166534}.queue-state.failed{background:#fee2e2;color:#991b1b}.drawer{border-top:1px solid var(--line);margin-top:14px;padding-top:12px}.hide{display:none!important}@media(max-width:700px){main{padding:16px 12px}.rail button{padding:10px 12px;font-size:12px}.panel{padding:14px}.row .grow{flex:1 1 100%}}\n</style></head><body><main>\n<h1>Auto Stream</h1><p class=\"lede\">Independent prerecorded YouTube Live studio · one stream supervisor · Auto Uploader data remains isolated.</p>\n<nav class=\"rail\" aria-label=\"Auto Stream primary tabs\">\n<button data-tab=\"dashboard\" aria-selected=\"true\">Dashboard</button>\n<button data-tab=\"channels\" aria-selected=\"false\">Channels</button>\n<button data-tab=\"sheets-sync\" aria-selected=\"false\">Sheets Sync</button>\n<button data-tab=\"live-studio\" aria-selected=\"false\">Live Studio</button>\n<button data-tab=\"live-queue\" aria-selected=\"false\">Live Queue</button>\n</nav>\n<section id=\"dashboard\" role=\"tabpanel\" class=\"panel\">\n<h2>Dashboard</h2><div class=\"grid\"><div class=\"stat\"><b id=\"channel-count\">0</b><span>Authorized channels</span></div><div class=\"stat\"><b id=\"job-count\">0</b><span>Queued jobs</span></div><div class=\"stat\"><b id=\"active-count\">0</b><span>Encoder sessions</span></div><div class=\"stat\"><b id=\"health-state\">—</b><span>Engine health</span></div></div>\n<p id=\"health\" class=\"message\">Loading status…</p>\n<div class=\"drawer\"><details><summary>Admin OAuth client setup</summary><p class=\"muted\">Stored encrypted on VPS; this panel never exposes the secret and is not a primary tab.</p><div class=\"grid\"><div><label>Client ID</label><input id=\"oauth-client-id\" autocomplete=\"off\"></div><div><label>Client Secret</label><input id=\"oauth-client-secret\" type=\"password\" autocomplete=\"new-password\"></div></div><div class=\"row\"><button class=\"primary\" id=\"save-oauth\">Save OAuth Client</button><button id=\"remove-oauth\">Remove Saved Client</button></div><p id=\"oauth-state\" class=\"muted\"></p></details></div>\n</section>\n<section id=\"channels\" role=\"tabpanel\" class=\"panel hide\"><div class=\"row\"><div class=\"grow\"><h2>Channels</h2><p class=\"muted\">Inventory and authorization are separate. Metadata import never grants Live access.</p></div><button class=\"primary\" id=\"connect-youtube\">Connect YouTube channel</button><button id=\"refresh-channels\">Refresh</button></div><div id=\"channel-list\"></div><div class=\"drawer\"><h3>Import inventory metadata</h3><div class=\"grid\"><div><label>Channel ID</label><input id=\"import-channel-id\" placeholder=\"UC…\"></div><div><label>Channel name</label><input id=\"import-channel-title\"></div></div><button id=\"import-channel\">Import metadata only</button></div></section>\n<section id=\"sheets-sync\" role=\"tabpanel\" class=\"panel hide\"><h2>Sheets Sync</h2><p class=\"muted\">Separate read-only channel inventory/schedule source. Preview and Sync create DRAFT records only; they never start a stream.</p><div class=\"grid\"><div><label>Authorized channel</label><select id=\"sheet-channel\"></select></div><div><label>Spreadsheet ID</label><input id=\"sheet-id\"></div><div><label>A1 range</label><input id=\"sheet-range\" value=\"Sheet1!A1:Z200\"></div></div><button class=\"primary\" id=\"add-sheet\">Add Sheet Source</button><div id=\"sheet-list\"></div></section>\n<section id=\"live-studio\" role=\"tabpanel\" class=\"panel hide\"><h2>Live Studio</h2><p class=\"muted\">Prepare media before streaming. OAuth mode controls YouTube resources; manual-key mode controls encoder delivery only.</p><div class=\"grid\"><div><label>Authorized channel</label><select id=\"job-channel\"></select></div><div><label>Media path</label><input id=\"job-media\" placeholder=\"uploads/video.mp4\"></div><div><label>Title</label><input id=\"job-title\" maxlength=\"100\"></div><div><label>Loop count</label><input id=\"job-loops\" type=\"number\" min=\"1\" value=\"1\"></div></div><label>Description</label><textarea id=\"job-description\" rows=\"3\"></textarea><div class=\"row\"><label><input id=\"job-unlimited\" type=\"checkbox\"> Unlimited loop</label><label>Privacy <select id=\"job-privacy\"><option>private</option><option>unlisted</option><option>public</option></select></label><label class=\"grow\">PC video <input id=\"media-file\" type=\"file\" accept=\"video/*\"></label><button id=\"upload-media\">Upload and checksum</button></div><p id=\"studio-note\" class=\"message\">Publishing and Go Live are OFF by default.</p><button class=\"primary\" id=\"create-job\">Create DRAFT / queue</button><div class=\"drawer\"><h3>Manual RTMPS control</h3><p class=\"muted\">The stream key is sent only over the authenticated HTTPS request and is never saved in the job database or browser storage.</p><div class=\"grid\"><div><label>RTMPS ingest URL</label><input id=\"manual-url\" value=\"rtmps://a.rtmps.youtube.com/live2\"></div><div><label>Stream key</label><input id=\"manual-key\" type=\"password\" autocomplete=\"off\"></div></div><button class=\"btn warn\" id=\"manual-start\">Start manual RTMPS for selected queue item</button></div></section>\n<section id=\"live-queue\" role=\"tabpanel\" class=\"panel hide\"><div class=\"row\"><div class=\"grow\"><h2>Live Queue</h2><p class=\"muted\">Durable states are local truth; YouTube LIVE is shown only after remote verification.</p></div><button id=\"refresh-jobs\">Refresh</button></div><div id=\"job-list\"></div></section>\n<div id=\"msg\" class=\"message hide\" role=\"status\" aria-live=\"polite\"></div>\n</main>\n<script>\n\"use strict\";\nconst root=\"/short-stream/engine\";\nconst qs=id=>document.getElementById(id), msg=qs(\"msg\");\nlet channels=[],jobs=[],flags={};\nfunction note(s){msg.textContent=s;msg.classList.remove(\"hide\")}\nasync function api(path,method=\"GET\",body=null,form=false){const r=await fetch(root+path,{method,credentials:\"same-origin\",headers:form?{}:(body?{\"Content-Type\":\"application/json\"}:{}),body:form?body:(body?JSON.stringify(body):undefined)});let p={};try{p=await r.json()}catch(_){ }if(!r.ok)throw Error(typeof p.detail===\"string\"?p.detail:\"Request failed\");return p}\nfunction render(id,items,fn){const el=qs(id);el.replaceChildren();if(!items.length){el.innerHTML='<p class=\"muted\">None yet.</p>';return}items.forEach(x=>{const d=document.createElement(\"div\");d.className=\"item\";fn(d,x);el.appendChild(d)})}\nfunction addText(el,text,cls=\"\"){const p=document.createElement(\"p\");p.textContent=text;if(cls)p.className=cls;el.appendChild(p)}\nfunction fillChannels(){for(const id of [\"sheet-channel\",\"job-channel\"]){const s=qs(id);s.replaceChildren();channels.filter(c=>c.authorized).forEach(c=>{const o=document.createElement(\"option\");o.value=c.id;o.textContent=c.title+\" (\"+c.id+\")\";s.appendChild(o)})}}\nasync function loadChannels(){channels=(await api(\"/channels\")).channels||[];render(\"channel-list\",channels,(el,c)=>{addText(el,c.title+\" — \"+c.id);addText(el,c.authorized?\"OAuth Live authorization verified\":\"Inventory-only; connect OAuth for Live control\",\"muted\");if(c.authorized){const b=document.createElement(\"button\");b.textContent=\"Disconnect\";b.onclick=async()=>{try{await api(\"/channels/\"+encodeURIComponent(c.id)+\"/disconnect\",\"POST\");loadChannels()}catch(e){note(e.message)}};el.appendChild(b)}});fillChannels()}\nasync function loadSheets(){const data=await api(\"/sheets\");render(\"sheet-list\",data.sources||[],(el,s)=>{addText(el,s.channel_id+\" — \"+s.spreadsheet_id+\" — \"+s.a1_range,\"mono\");const row=document.createElement(\"div\");row.className=\"row\";for(const [label,dry] of [[\"Preview\",true],[\"Sync DRAFTs\",false]]){const b=document.createElement(\"button\");b.textContent=label;b.onclick=async()=>{try{const r=await api(\"/sheets/\"+encodeURIComponent(s.id)+\"/sync?dry_run=\"+dry,\"POST\");note(\"Rows: \"+r.total+\" · Drafts: \"+r.created+\" · Errors: \"+r.errors.length)}catch(e){note(e.message)}};row.appendChild(b)}el.appendChild(row)})}\nfunction jobText(j){return j.title+\" · \"+j.id+\" · \"+j.status}\nasync function loadJobs(){jobs=(await api(\"/jobs\")).jobs||[];render(\"job-list\",jobs,(el,j)=>{addText(el,jobText(j));addText(el,\"Channel: \"+j.channel_id+\" · mode: \"+(j.mode||\"OAuth/manual\") ,\"muted\");const row=document.createElement(\"div\");row.className=\"row\";const prep=document.createElement(\"button\");prep.textContent=\"Prepare\";prep.disabled=![\"DRAFT\",\"READY\",\"SCHEDULED\"].includes(j.status);prep.onclick=async()=>{try{await api(\"/jobs/\"+j.id+\"/prepare\",\"POST\");loadJobs()}catch(e){note(e.message)}};row.appendChild(prep);const oauth=document.createElement(\"button\");oauth.textContent=\"Create private OAuth broadcast\";oauth.disabled=!flags.youtube_mutations_enabled||![\"READY\",\"SCHEDULED\"].includes(j.status);oauth.onclick=async()=>{try{await api(\"/jobs/\"+j.id+\"/broadcast/provision\",\"POST\");loadJobs();note(\"Private YouTube broadcast created; not Live.\")}catch(e){note(e.message)}};row.appendChild(oauth);const verify=document.createElement(\"button\");verify.textContent=\"Verify remote\";verify.onclick=async()=>{try{const r=await api(\"/jobs/\"+j.id+\"/broadcast/verify\");note(\"YouTube=\"+r.youtube_broadcast_status+\" · ingest=\"+r.youtube_ingest_status+\" · verifiedLive=\"+r.youtube_verified_live)}catch(e){note(e.message)}};row.appendChild(verify);const stop=document.createElement(\"button\");stop.textContent=\"Stop\";stop.disabled=![\"STARTING\",\"INGESTING\",\"STOPPING\"].includes(j.status);stop.onclick=async()=>{try{await api(\"/jobs/\"+j.id+\"/stop\",\"POST\");loadJobs()}catch(e){note(e.message)}};row.appendChild(stop);el.appendChild(row)})}\nasync function loadHealth(){const [h,i,y]=await Promise.all([api(\"/health\"),api(\"/integrations/health\"),api(\"/youtube/health\")]);flags={...y};qs(\"channel-count\").textContent=i.channels_connected;qs(\"job-count\").textContent=jobs.length;qs(\"active-count\").textContent=h.encoder_sessions;qs(\"health-state\").textContent=h.ok?\"OK\":\"DEGRADED\";qs(\"health\").textContent=\"Engine=\"+(h.ok?\"connected\":\"unavailable\")+\" · encoder=\"+h.encoder_sessions+\" · publishing=\"+(h.publishing_enabled?\"ON\":\"OFF\")+\" · YouTube LIVE is remote-only\";qs(\"studio-note\").textContent=\"OAuth mutations=\"+(y.youtube_mutations_enabled?\"ON\":\"OFF\")+\" · FFmpeg publishing=\"+(y.publishing_enabled?\"ON\":\"OFF\")+\" · Go Live=\"+(y.go_live_enabled?\"ON\":\"OFF\")}\nasync function saveOAuth(){try{await api(\"/oauth/client\",\"POST\",{client_id:qs(\"oauth-client-id\").value.trim(),client_secret:qs(\"oauth-client-secret\").value},{})}catch(e){note(e.message)}}\nqs(\"connect-youtube\").onclick=async()=>{try{const r=await api(\"/oauth/start?with_sheets=0\");location.assign(r.authorization_url)}catch(e){note(e.message)}};\nqs(\"refresh-channels\").onclick=()=>loadChannels().catch(e=>note(e.message));\nqs(\"import-channel\").onclick=async()=>{try{await api(\"/channels/import\",\"POST\",{channel_id:qs(\"import-channel-id\").value,title:qs(\"import-channel-title\").value});loadChannels();note(\"Inventory metadata imported; authorization still required.\")}catch(e){note(e.message)}};\nqs(\"add-sheet\").onclick=async()=>{try{await api(\"/sheets\",\"POST\",{channel_id:qs(\"sheet-channel\").value,spreadsheet_id:qs(\"sheet-id\").value,a1_range:qs(\"sheet-range\").value});loadSheets();note(\"Sheet source linked; no stream started.\")}catch(e){note(e.message)}};\nqs(\"upload-media\").onclick=async()=>{const f=qs(\"media-file\").files[0];if(!f){note(\"Choose a video first.\");return}const form=new FormData();form.append(\"file\",f);try{const r=await api(\"/media/upload\",\"POST\",form,true);qs(\"job-media\").value=r.media_path;note(\"Uploaded \"+r.bytes+\" bytes; SHA-256 \"+r.sha256)}catch(e){note(e.message)}};\nqs(\"create-job\").onclick=async()=>{try{const c=qs(\"job-channel\").value;if(!c)throw Error(\"Select an authorized channel.\");const j=await api(\"/jobs\",\"POST\",{channel_id:c,media_path:qs(\"job-media\").value.trim(),title:qs(\"job-title\").value.trim(),description:qs(\"job-description\").value,privacy:qs(\"job-privacy\").value,loop_count:+qs(\"job-loops\").value,unlimited:qs(\"job-unlimited\").checked,idempotency_key:\"studio-\"+(crypto.randomUUID?crypto.randomUUID():String(Date.now()))});note(\"DRAFT created \"+j.id+\"; prepare it before any external action.\");loadJobs()}catch(e){note(e.message)}};\nqs(\"manual-start\").onclick=async()=>{const j=jobs.find(x=>[\"READY\",\"SCHEDULED\"].includes(x.status));if(!j){note(\"Prepare a READY job first.\");return}try{const r=await api(\"/jobs/\"+j.id+\"/broadcast/manual-ingest\",\"POST\",{ingest_url:qs(\"manual-url\").value,stream_key:qs(\"manual-key\").value});qs(\"manual-key\").value=\"\";note(\"Manual encoder started. YouTube LIVE must be verified in YouTube Studio.\");loadJobs()}catch(e){note(e.message)}};\nqs(\"save-oauth\").onclick=async()=>{try{const r=await api(\"/oauth/client\",\"POST\",{client_id:qs(\"oauth-client-id\").value.trim(),client_secret:qs(\"oauth-client-secret\").value});qs(\"oauth-client-secret\").value=\"\";qs(\"oauth-state\").textContent=\"Saved encrypted OAuth client: \"+r.client_id}catch(e){note(e.message)}};\nqs(\"remove-oauth\").onclick=async()=>{try{await api(\"/oauth/client\",\"DELETE\");qs(\"oauth-state\").textContent=\"Saved client removed.\"}catch(e){note(e.message)}};\nqs(\"refresh-jobs\").onclick=()=>loadJobs().catch(e=>note(e.message));\nconst tabs=[...document.querySelectorAll(\"[data-tab]\")], identity=document.querySelector(\"meta[name=vps1-username]\")?.content||\"\", stateKey=identity?\"vps1.autostream.tab.v2:\"+identity:\"\";\nfunction openTab(id){if(!tabs.some(x=>x.dataset.tab===id))id=\"dashboard\";tabs.forEach(x=>x.setAttribute(\"aria-selected\",String(x.dataset.tab===id)));document.querySelectorAll(\"[role=tabpanel]\").forEach(x=>x.classList.toggle(\"hide\",x.id!==id));if(stateKey)try{sessionStorage.setItem(stateKey,id)}catch(_){}}\ntabs.forEach(x=>x.onclick=()=>openTab(x.dataset.tab));let restore=\"dashboard\";if(stateKey)try{restore=sessionStorage.getItem(stateKey)||\"dashboard\"}catch(_){}openTab(restore);\nasync function refreshAll(){try{await loadChannels();await loadSheets();await loadJobs();await loadHealth()}catch(e){note(e.message)}}refreshAll();setInterval(refreshAll,8000);\n</script></body></html>"


@router.get("/studio", response_class=HTMLResponse)
def studio():
    return HTMLResponse(PAGE)
